"""Generate the SYNTHETIC fixture for test_compare_comsol.py (never a result, never under results/).

    python code/tests/fixtures/make_comsol_synthetic.py

Construction with hand-checkable differences:  Python y_O2 = linear 0..1 on 11 points, COMSOL = Python + 0.1
(NRMSE 0.1); Python T = 300..400 K, COMSOL = Python + 5 K (NRMSE 0.05); t_spec 100 s vs 101 s (diff 1 s);
m_H2_consumed 2.0 vs 2.2 kg (RE 0.1).
"""
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent / "comsol_synthetic"
BANNER = "# SYNTHETIC FIXTURE - not a result, not COMSOL output, generated by make_comsol_synthetic.py"
COLS = "case_id,model,grid_id,rtol,t_s,T_out_K,y_H2_out,y_O2_out,y_H2O_out,y_N2_out,F_out_mol_s,p_out_Pa"
EVCOLS = ("case_id,model,grid_id,rtol,m_H2_consumed_kg,m_H2_vented_kg,m_H2_purge_kg,m_H2_repress_kg,t_spec_s,t_break_s,"
          "mass_balance_err,energy_balance_err,wall_s")


def series(path: Path, model: str, d_y: float, d_T: float):
    t = np.linspace(0.0, 100.0, 11)
    y = np.linspace(0.0, 1.0, 11) + d_y
    T = np.linspace(300.0, 400.0, 11) + d_T
    lines = [BANNER, COLS]
    for ti, yi, Ti in zip(t, y, T):
        lines.append(f"SYNTHETIC_case,{model},N400,1e-06,{ti:g},{Ti:.10g},nan,{yi:.10g},nan,nan,nan,nan")
    path.write_text("\n".join(lines) + "\n")


def events(path: Path, model: str, consumed: float, t_spec: float):
    path.write_text("\n".join([BANNER, EVCOLS,
                               f"SYNTHETIC_case,{model},N400,1e-06,{consumed},nan,nan,nan,{t_spec},nan,1e-9,nan,1.0"]) + "\n")


if __name__ == "__main__":
    (HERE / "comsol_outputs").mkdir(parents=True, exist_ok=True)
    (HERE / "python_ver6").mkdir(parents=True, exist_ok=True)
    series(HERE / "comsol_outputs" / "SYNTHETIC_case__comsol__N400.csv", "comsol", 0.1, 5.0)
    series(HERE / "python_ver6" / "SYNTHETIC_case__python_mol__N400.csv", "python_mol", 0.0, 0.0)
    events(HERE / "comsol_outputs" / "ver6_events.csv", "comsol", 2.2, 101.0)
    events(HERE / "python_ver6" / "ver6_events.csv", "python_mol", 2.0, 100.0)
    print("fixture written to", HERE)
